from collections import deque


def ordering(s, ws):
    pbs = {}
    for p in sorted(s):
        pbs.setdefault(p[1]-p[0], deque()).append(p)

    o = []
    os = set()
    for w in ws:
        try:
            p = pbs[w].popleft()
        except (IndexError, KeyError):
            return None

        if ((p[0] > 0 and (p[0]-1, p[1]) not in os)
            or (p[1] > 0 and (p[0], p[1]-1) not in os)):
            return None

        o.append(p)
        os.add(p)


    return o


