def graph(e):
    e = [(w, i, b) for i, (w, b) in enumerate(e)]
    e.sort()

    g = [None]*len(e)

    mst = [(w, i) for w, i, b in e if b]
    for n, (w, i) in enumerate(mst, 2):
        g[i] = 1, n

    cm = 0
    available = []

    for w, i, b in e:
        if not b:
            if not available:
                cm += 1
                if mst[cm][0] > w:
                    return None
                available = [(u, cm+2) for u in range(2, cm+2)]
            g[i] = available.pop()
    return g


