    distances[s] = 0
    for i in range(n):
        _, v = min((distances[j], j) for j in range(n) if not visited[j])
        visited[v] = True
        for to, length in graph[v]:
            if distances[to] > distances[v] + length:
                distances[to] = distances[v] + length
                ancestors[to] = v
    return ancestors, distances


