def make_dfs(G):
    vis = {i: False for i in G}
    cols = {i: [] for i in G}

    def dfs(u, color=None):
        if color is None:
            color = u
        vis[u] = True
        cols[color].append(u)
        for v in G[u]:
            if not vis[v]:
                dfs(v, color)
        return cols[color]

    return dfs, vis


