  for start in cyc:
    stack = [(v, start) for v in graph[start] if v not in cyc]
    while stack:
      vertex, parent = stack.pop()
      visited.add(vertex)
      for neighbour in graph[vertex]:
        if neighbour != parent:
          if neighbour in visited:
            return set()
          stack.append((neighbour, vertex))
  return visited


