class Vector:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    
    def __add__(self, other):
        return Vector(self.x + other.x, self.y + other.y)
    
    def __sub__(self, other):
        return Vector(self.x - other.x, self.y - other.y)
    
    def to(self, other):
        return other - self
    
    def __repr__(self):
        return "(%s %s)" % (self.x, self.y)

    def dot(self, other):
        return self.x * other.y - self.y * other.x
    
    def lensq(self):
        return self.x ** 2 + self.y ** 2

